mapper.select:
select x.id, sum(x.reference_count)::bigint as "referenceCount" from (
  select id, (select count(*) from cm_exam_subject where certification_id = id) reference_count from cm_exam_certification where id in #{id}
  union all select id, (select count(*) from cm_user_goal where certification_id = id) from cm_exam_certification where id in #{id}
  union all select id, (select count(*) from cm_exam_schedule where certification_id = id) from cm_exam_certification where id in #{id}
  union all select id, (select count(*) from cm_collection where certification_id = id) from cm_exam_certification where id in #{id}
) x group by x.id

select x.id, sum(x.reference_count)::bigint as "referenceCount" from (
  select id, (select count(*) from cm_knowledge_point where syllabus_version_id = id) reference_count from cm_syllabus_version where id in #{id}
  union all select id, (select count(*) from cm_knowledge_prerequisite where syllabus_version_id = id) from cm_syllabus_version where id in #{id}
  union all select id, (select count(*) from cm_document where syllabus_version_id = id) from cm_syllabus_version where id in #{id}
  union all select id, (select count(*) from cm_import_batch where syllabus_version_id = id) from cm_syllabus_version where id in #{id}
  union all select id, (select count(*) from cm_user_goal where syllabus_version_id = id) from cm_syllabus_version where id in #{id}
  union all select id, (select count(*) from cm_collection where syllabus_version_id = id) from cm_syllabus_version where id in #{id}
) x group by x.id

mapper.delete:
delete from cm_knowledge_import_diff where import_batch_id in (
    select ib.id from cm_import_batch ib join cm_syllabus_version sv on sv.id=ib.syllabus_version_id
    where sv.certification_id=#{certificationId}
)

delete from cm_knowledge_import_diff where import_batch_id in (
    select id from cm_import_batch where syllabus_version_id=#{syllabusVersionId}
)

mapper.select:
select distinct object_key from (
    select source_file_path as object_key from cm_syllabus_version where id=#{syllabusVersionId}
    union
    select batch.source_file_path as object_key from cm_import_batch batch
    left join cm_document document on document.id=batch.document_id
    where batch.syllabus_version_id=#{syllabusVersionId} or document.syllabus_version_id=#{syllabusVersionId}
) storage_objects where coalesce(trim(object_key), '') <> ''

select distinct object_key from (
    select source_file_path as object_key from cm_syllabus_version where certification_id=#{certificationId}
    union
    select document.source_file_path as object_key from cm_document document
    left join cm_syllabus_version document_version on document_version.id=document.syllabus_version_id
    where document.certification_id=#{certificationId} or document_version.certification_id=#{certificationId}
    union
    select batch.source_file_path as object_key from cm_import_batch batch
    left join cm_syllabus_version version on version.id=batch.syllabus_version_id
    left join cm_document document on document.id=batch.document_id
    left join cm_syllabus_version document_version on document_version.id=document.syllabus_version_id
    where batch.certification_id=#{certificationId}
       or version.certification_id=#{certificationId}
       or document.certification_id=#{certificationId}
       or document_version.certification_id=#{certificationId}
) storage_objects where coalesce(trim(object_key), '') <> ''
